Element* MaxHeap::DeleteMax(Element& x)
{
if (n == 0) {HeapEmpty(); return 0;}
x = heap[1];
Element last = heap[n];
n--;
for (int i = 1, j = 2; j <= n; i = j, j *= 2) {
if (j < n)
if (heap[j].key < heap[j+1].key) j++;
// j points to the larger child
if (last.key >= heap[j].key) break;
heap[i] = heap[j]; // move child up
}
heap[i] = last;
return &x;
}

